#!/usr/bin/env node
/**
 * Turn `skills/<name>/SKILL.md` into `agent/src/skills-bundle.ts`.
 *
 * The agent reaches a machine as ONE file — `deploy/build-agent.sh` bundles
 * `agent/src/main.ts` with esbuild and the installers fetch that single
 * `agent.mjs` from the hub. So the skills have to travel INSIDE the bundle;
 * a second downloadable artifact would mean touching install-mac.sh,
 * install-win.ps1 and every already-installed machine.
 *
 * The generated file is committed so `npm run dev --workspace agent` (tsx, no
 * build step) sees the same skills the bundle would carry. Regenerate with
 * `npm run gen:skills --workspace agent`; build-agent.sh does it automatically.
 *
 * Usage: node agent/scripts/gen-skills-bundle.mjs
 */
import { readFileSync, readdirSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, '..', '..');
const skillsDir = join(repoRoot, 'skills');
const outFile = join(repoRoot, 'agent', 'src', 'skills-bundle.ts');

if (!existsSync(skillsDir)) {
  console.error(`[gen-skills] no skills/ directory at ${skillsDir}`);
  process.exit(1);
}

const names = readdirSync(skillsDir, { withFileTypes: true })
  .filter((e) => e.isDirectory() && existsSync(join(skillsDir, e.name, 'SKILL.md')))
  .map((e) => e.name)
  .sort();

if (names.length === 0) {
  console.error('[gen-skills] skills/ has no <name>/SKILL.md — refusing to write an empty bundle');
  process.exit(1);
}

// A skill's directory name IS its slash-command name, so anything that is not a
// plain slug would produce an uninvokable skill — and it lands in a path we
// write to, which makes a stray `..` a real problem rather than a typo.
const bad = names.filter((n) => !/^[a-z0-9][a-z0-9-]*$/.test(n));
if (bad.length) {
  console.error(`[gen-skills] not usable as skill names: ${bad.join(', ')}`);
  process.exit(1);
}

const entries = names.map((name) => {
  // Normalise the line endings the CHECKOUT happened to have. A Windows clone
  // (autocrlf, and this repo carries no .gitattributes) hands us `\r\n`, which
  // JSON.stringify would bake into the bundle as a literal `\r\n` escape — a
  // diff that survives git's own normalisation, and skills written to every
  // machine's ~/.claude/skills with carriage returns in them. The generated
  // file has to be a function of the skill bodies, not of who built it.
  const body = readFileSync(join(skillsDir, name, 'SKILL.md'), 'utf8').replace(/\r\n/g, '\n');
  // JSON.stringify handles every escape a Markdown body can contain — backticks,
  // backslashes, `${`, newlines — without a hand-rolled escaper to get wrong.
  return `  [${JSON.stringify(name)}, ${JSON.stringify(body)}],`;
});

const out = `// AUTO-GENERATED by agent/scripts/gen-skills-bundle.mjs — do not edit.
// Source of truth: skills/<name>/SKILL.md at the repo root.
// Regenerate: npm run gen:skills --workspace agent

/** Skill name -> the full text of its SKILL.md, carried inside the agent bundle. */
export const BUNDLED_SKILLS: ReadonlyMap<string, string> = new Map([
${entries.join('\n')}
]);
`;

writeFileSync(outFile, out);
console.log(`[gen-skills] ${names.length} skill(s) -> agent/src/skills-bundle.ts (${out.length} bytes)`);
console.log(`[gen-skills] ${names.join(', ')}`);
